#include "manager.h"
#include <stddef.h>
static struct nova_managed_service *find_service(struct nova_service_manager *m,uint32_t id){size_t i;if(!m||!id)return 0;for(i=0;i<NOVA_MANAGER_MAX_SERVICES;i++)if(m->services[i].service_id==id)return &m->services[i];return 0;}
void nova_service_manager_init(struct nova_service_manager *m){size_t i;if(!m)return;for(i=0;i<NOVA_MANAGER_MAX_SERVICES;i++){m->services[i].service_id=0;m->services[i].task_id=0;m->services[i].endpoint=0;m->services[i].state=NOVA_MANAGED_STOPPED;}}
int nova_service_manager_register(struct nova_service_manager *m,uint32_t id){size_t i;if(!m||!id||find_service(m,id))return 0;for(i=0;i<NOVA_MANAGER_MAX_SERVICES;i++)if(!m->services[i].service_id){m->services[i].service_id=id;m->services[i].task_id=0;m->services[i].endpoint=0;m->services[i].state=NOVA_MANAGED_STOPPED;return 1;}return 0;}
int nova_service_manager_begin_start(struct nova_service_manager *m,uint32_t id,uint32_t task){struct nova_managed_service *s=find_service(m,id);if(!s||!task||(s->state!=NOVA_MANAGED_STOPPED&&s->state!=NOVA_MANAGED_FAILED))return 0;s->task_id=task;s->endpoint=0;s->state=NOVA_MANAGED_STARTING;return 1;}
int nova_service_manager_publish(struct nova_service_manager *m,uint32_t id,uint32_t task,uint32_t endpoint){struct nova_managed_service *s=find_service(m,id);if(!s||!task||!endpoint||s->state!=NOVA_MANAGED_STARTING||s->task_id!=task)return 0;s->endpoint=endpoint;s->state=NOVA_MANAGED_RUNNING;return 1;}
int nova_service_manager_begin_stop(struct nova_service_manager *m,uint32_t id,uint32_t task){struct nova_managed_service *s=find_service(m,id);if(!s||!task||s->state!=NOVA_MANAGED_RUNNING||s->task_id!=task)return 0;s->state=NOVA_MANAGED_STOPPING;return 1;}
int nova_service_manager_complete_stop(struct nova_service_manager *m,uint32_t id,uint32_t task){struct nova_managed_service *s=find_service(m,id);if(!s||!task||s->state!=NOVA_MANAGED_STOPPING||s->task_id!=task)return 0;s->task_id=0;s->endpoint=0;s->state=NOVA_MANAGED_STOPPED;return 1;}
int nova_service_manager_fail(struct nova_service_manager *m,uint32_t id,uint32_t task){struct nova_managed_service *s=find_service(m,id);if(!s||!task||s->task_id!=task||(s->state!=NOVA_MANAGED_STARTING&&s->state!=NOVA_MANAGED_RUNNING&&s->state!=NOVA_MANAGED_STOPPING))return 0;s->task_id=0;s->endpoint=0;s->state=NOVA_MANAGED_FAILED;return 1;}
int nova_service_manager_get(const struct nova_service_manager *m,uint32_t id,struct nova_managed_service *out){size_t i;if(!m||!id||!out)return 0;for(i=0;i<NOVA_MANAGER_MAX_SERVICES;i++)if(m->services[i].service_id==id){*out=m->services[i];return 1;}return 0;}
